        {
          "dimension": "resource preservation",
          "fact": "C2 follows suit while preserving the planned queen entry.",
          "explanation": "South's CA is unbeatable in the current trick. North holds CQ C7 C2, so playing C2 retains CQ and C7 for the crossing and return.",
          "quotes": [
            "Play low under the ace, preserving the queen as a club winner and entry for the planned club continuation."
          ]
        }
      ]
    },
    {
      "id": "decision-0005",
      "status": "pass",
      "findings": [
        {
          "dimension": "feasibility and visibility",
          "fact": "C4 provides the planned crossing to CQ without assuming an unobserved break.",
          "explanation": "West played C3 and East C5 under CA. South retains CK C8 C6 C4 and North CQ C7; no outstanding club can beat CQ.",
          "quotes": [
            "Lead a low club to dummy’s queen as planned. Both defenders followed to the ace; continue developing clubs while retaining the king in hand."
          ]
