        {
          "dimension": "winners and continuation",
          "fact": "CQ wins and leaves a feasible club return toward CK.",
          "explanation": "CQ beats West's C9, and the outstanding CJ and CT cannot overtake it. North retains C7 to lead toward South's CK.",
          "quotes": [
            "Win with the club queen as planned, then return dummy’s remaining club toward the king to continue establishing the suit."
          ]
        }
      ]
    },
    {
      "id": "decision-0007",
      "status": "pass",
      "findings": [
        {
          "dimension": "distribution inference and trick counting",
          "fact": "The observed cards establish a 3–2 club break and ten available tricks.",
          "explanation": "The defenders began with five clubs and have each followed twice: West C3 C9, East C5 CT. Only CJ remains. C7 toward CK draws it, establishing C8 C6; five club tricks plus DA DK SA HA HK total ten.",
          "quotes": [
            "Both defenders followed twice, so clubs are 3–2; the king will draw the remaining jack, establishing ten tricks.",
            "Lead C7 to South's king to draw the last opposing club, then cash the two established clubs."
          ]
        }
      ]
    },
    {
      "id": "decision-0008",
      "status": "pass",
      "findings": [
        {
          "dimension": "authorized inference",
          "fact": "West's remaining CJ is established by public play.",
          "explanation": "C3 C5 C9 CT have been played, leaving CJ as the only opposing club. East's H2 discard establishes that West holds it. South's CK wins and establishes C8 C6.",
          "quotes": [
            "Win with the club king, drawing West’s remaining jack and establishing both remaining clubs for ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0009",
      "status": "pass",
      "findings": [
        {
          "dimension": "established winners",
          "fact": "C8 and C6 are established winners and the ten-trick count is sound.",
          "explanation": "West's CJ fell under CK, exhausting all opposing clubs. Declarer has four tricks, two remaining club winners, and DK SA HA HK available with heart communication.",
          "quotes": [
            "Cash an established club. Both remaining clubs are winners, and the top cards in the other suits ensure ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0010",
      "status": "pass",
      "findings": [
        {
          "dimension": "discard and communications",
          "fact": "Discarding D5 preserves all resources needed for ten tricks.",
          "explanation": "North has no clubs and may discard D5 on the established C8. North retains HK H7 H4, while South retains HA H6 H3, DK and C6.",
          "quotes": [
            "Discard a low diamond on the winning club, preserving the heart king and safe heart entries. Ten tricks remain assured."
          ]
        }
      ]
    },
    {
      "id": "decision-0011",
      "status": "pass",
      "findings": [
        {
          "dimension": "trick counting",
          "fact": "C6 and four outside winners bring the total to ten.",
          "explanation": "Declarer has five tricks. All opposing clubs are exhausted, so C6 wins; DK SA HA HK supply four additional tricks with available heart communication.",
          "quotes": [
            "Cash the last established club, then collect the four remaining top winners for ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0012",
      "status": "pass",
